import{_ as e,o as l,c as r,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const c=JSON.parse('{"title":"Κέντρο βοήθειας","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/index.md","filePath":"el/help/index.md"}'),t={name:"el/help/index.md"};function h(o,a,n,s,p,d){return l(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="κεντρο-βοηθειας" tabindex="-1">Κέντρο βοήθειας <a class="header-anchor" href="#κεντρο-βοηθειας" aria-label="Permalink to &quot;Κέντρο βοήθειας&quot;">​</a></h1><h2 id="αναφορα-πελατων" tabindex="-1">Αναφορά πελατών <a class="header-anchor" href="#αναφορα-πελατων" aria-label="Permalink to &quot;Αναφορά πελατών&quot;">​</a></h2><ul><li><a href="/el/help/faq.html">Συχνές ερωτήσεις</a></li><li><a href="/el/help/glossary.html">Γλωσσάρι όρων</a></li><li><a href="/el/help/feature-availability.html">Πίνακας διαθεσιμότητας λειτουργιών</a></li></ul><h2 id="δεν-μπορω-να-δημιουργησω-κρατηση" tabindex="-1">Δεν μπορώ να δημιουργήσω κράτηση <a class="header-anchor" href="#δεν-μπορω-να-δημιουργησω-κρατηση" aria-label="Permalink to &quot;Δεν μπορώ να δημιουργήσω κράτηση&quot;">​</a></h2><p>Ελέγξτε τον ρόλο, την ενεργή περιοχή, την κατηγορία οχήματος, τη διαδρομή και την επαληθευμένη προσφορά. Δείτε τη <a href="/el/plus/create-reservation.html">δημιουργία κράτησης</a>.</p><h2 id="ο-πελατης-δεν-εχει-email" tabindex="-1">Ο πελάτης δεν έχει email <a class="header-anchor" href="#ο-πελατης-δεν-εχει-email" aria-label="Permalink to &quot;Ο πελάτης δεν έχει email&quot;">​</a></h2><p>Στο TransferBook+ το email είναι προαιρετικό. Καταχωρίστε το πραγματικό τηλέφωνο και αφήστε το email κενό. Δείτε τα <a href="/el/plus/passenger-information.html">στοιχεία επιβάτη</a>.</p><h2 id="απουσιαζει-τιμη-η-απαιτειται-προσφορα" tabindex="-1">Απουσιάζει τιμή ή απαιτείται προσφορά <a class="header-anchor" href="#απουσιαζει-τιμη-η-απαιτειται-προσφορα" aria-label="Permalink to &quot;Απουσιάζει τιμή ή απαιτείται προσφορά&quot;">​</a></h2><p>Η διαδρομή χωρίς τιμή δεν είναι δωρεάν υπηρεσία. Ακολουθήστε τη <a href="/el/plus/manual-quotations.html">χειροκίνητη προσφορά</a>.</p><h2 id="δεν-μπορω-να-αναθεσω-κρατηση" tabindex="-1">Δεν μπορώ να αναθέσω κράτηση <a class="header-anchor" href="#δεν-μπορω-να-αναθεσω-κρατηση" aria-label="Permalink to &quot;Δεν μπορώ να αναθέσω κράτηση&quot;">​</a></h2><p>Ελέγξτε την κατάσταση, την εκκρεμή προσφορά, τα δικαιώματα, τη διαθεσιμότητα οδηγού και τη χωρητικότητα. Δείτε το <a href="/el/plus/dispatch-schedule.html">πρόγραμμα αναθέσεων</a>.</p><h2 id="δεν-διατιθεται-μια-διασυνδεση" tabindex="-1">Δεν διατίθεται μια διασύνδεση <a class="header-anchor" href="#δεν-διατιθεται-μια-διασυνδεση" aria-label="Permalink to &quot;Δεν διατίθεται μια διασύνδεση&quot;">​</a></h2><p>Ελέγξτε τη ρύθμιση και την έγκριση της υπηρεσίας. Μην παρακάμπτετε απενεργοποιημένες λειτουργίες. Δείτε τις <a href="/el/integrations/">διασυνδέσεις</a>.</p><h2 id="αναλυτικη-αντιμετωπιση-προβληματων" tabindex="-1">Αναλυτική αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αναλυτικη-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αναλυτική αντιμετώπιση προβλημάτων&quot;">​</a></h2><ul><li><a href="/el/help/booking-problems.html">Προβλήματα φόρμας και υποβολής κράτησης</a></li><li><a href="/el/help/pricing-problems.html">Ελλιπείς τιμές και διαφορές τιμολόγησης</a></li><li><a href="/el/help/dispatch-problems.html">Συγκρούσεις και ελλιπείς αναθέσεις</a></li><li><a href="/el/help/access-and-session.html">Πρόσβαση, δικαιώματα και σφάλματα συνεδρίας</a></li><li><a href="/el/help/website-draft-problems.html">Προσχέδια που λείπουν και σφάλματα πακέτων</a></li><li><a href="/el/help/integration-problems.html">Μη διαθέσιμες διασυνδέσεις και αβέβαιες πληρωμές</a></li></ul>',15)])])}const f=e(t,[["render",h]]);export{c as __pageData,f as default};
